 let sun=eye+Vec3::new(-0.7,sun_h.abs().max(0.05),-0.45).normalize()*1500.;part(scene,MeshKey::Sphere,sun,Vec3::splat(if night{25.}else{38.}),Quat::IDENTITY,if night{c("#c6d4d2")}else{c("#ffe2a0")},flags::NO_FOG|flags::NO_SHADOW,2.);
 if night{for i in 0..90{let x=terrain::hash(i,4,11)*2.-1.;let y=terrain::hash(i,5,11);let z=terrain::hash(i,6,11)*2.-1.;part(scene,MeshKey::Sphere,eye+Vec3::new(x,y,z).normalize()*1700.,Vec3::splat(1.6),Quat::IDENTITY,c("#b4bdc7"),flags::NO_FOG|flags::NO_SHADOW,1.);}}
 for i in 0..20{let angle=i as f32*0.314;let p=Vec3::new(angle.cos()*1350.,30.,angle.sin()*1350.);part(scene,MeshKey::Cone,p,Vec3::new(370.,170.+(i%4) as f32*35.,260.),Quat::IDENTITY,horizon*0.53,flags::NO_FOG,0.);}
 if self.coarse.is_none(){let mut mesh=MeshData::default();for z in 0..=128{for x in 0..=128{let wx=x as f32*16.-1024.;let wz=z as f32*16.-1024.;let col=terrain::color(&g.data,wx,wz).0;mesh.vertices.push(Vertex{pos:[wx,terrain::height(&g.data,wx,wz)-0.25,wz],normal:[0.,1.,0.],uv:[0.,0.],color:[col[0],col[1],col[2],1.]});}}for z in 0..128{for x in 0..128{let n=(z*129+x) as u32;mesh.indices.extend([n,n+129,n+1,n+1,n+129,n+130]);}}self.coarse=Some(Arc::new(mesh));}
 scene.custom_meshes.push((MeshKey::Custom(0x7fff001),self.coarse.as_ref().unwrap().clone()));part(scene,MeshKey::Custom(0x7fff001),Vec3::ZERO,Vec3::ONE,Quat::IDENTITY,Vec3::ONE,0,0.);
 // River ribbons follow the carved channel.
 for w in g.data.world.river.windows(2){let a=Vec3::new(w[0][0],0.,w[0][1]);let b=Vec3::new(w[1][0],0.,w[1][1]);let delta=b-a;part(scene,MeshKey::Cube,(a+b)*0.5,Vec3::new(27.,0.12,delta.length()+4.),Quat::from_rotation_y(delta.x.atan2(delta.z)),c("#3d6a6a"),flags::NO_SHADOW,0.1);}

 if self.grass.is_none(){let mut m=MeshData::default();for blade in 0..20{let a=blade as f32*2.399;let offset=Vec3::new(a.sin()*0.43,0.,a.cos()*0.43);let side=Vec3::new(a.cos(),0.,-a.sin());let lean=Vec3::new(a.sin()*0.16,0.,a.cos()*0.16);let height=0.72+(blade%5) as f32*0.06;for k in 0..3{let t=k as f32/3.;let u=(k+1) as f32/3.;let center=|v:f32|offset+lean*v*v+Vec3::Y*(-0.5+height*v);let wa=side*(0.023*(1.-t)+0.001);let wb=side*(0.023*(1.-u)+0.001);m.push_quad([center(t)-wa,center(t)+wa,center(u)+wb,center(u)-wb],Vec3::Y);}}self.grass=Some(Arc::new(m));}
 scene.custom_meshes.push((MeshKey::Custom(0x7fff002),self.grass.as_ref().unwrap().clone()));
 // Vegetation is derived from the same terrain function that gives stealth cover.
 let cx=(eye.x/18.).floor() as i32;let cz=(eye.z/18.).floor() as i32;for z in cz-19..=cz+19{for x in cx-19..=cx+19{let h=terrain::hash(x,z,g.seed);if h<0.31{let wx=x as f32*18.+terrain::hash(x,z,4)*12.;let wz=z as f32*18.+terrain::hash(x,z,5)*12.;let p=Vec3::new(wx,terrain::height(&g.data,wx,wz),wz);if terrain::road(&g.data,flat(p))>8.&&!terrain::water(&g.data,flat(p))&&g.fire.at(flat(p))!=2{asset(scene,if h<0.025{"baobab"}else{"acacia"},p,Quat::from_rotation_y(h*20.),0.65+h*1.8,(x*199+z*37).unsigned_abs()+2000);}}}}
 let gx=(eye.x/2.).floor() as i32;let gz=(eye.z/2.).floor() as i32;for z in gz-32..=gz+32{for x in gx-32..=gx+32{let wx=x as f32*2.+terrain::hash(x,z,3)*1.8;let wz=z as f32*2.+terrain::hash(x,z,5)*1.8;let p=Vec3::new(wx,terrain::height(&g.data,wx,wz),wz);let d=distance(p,eye);if d>66.||terrain::grass(&g.data,flat(p))<0.5||g.fire.at(flat(p))==2{continue;}let h=0.65+terrain::hash(x,z,6)*0.38;let color=c("#c9a24b")*(0.90+terrain::hash(x,z,8)*0.14);part(scene,MeshKey::Custom(0x7fff002),p+Vec3::Y*h*0.48,Vec3::new(1.6,h,1.6),Quat::from_rotation_y(terrain::hash(x,z,9)*6.),color,flags::GRASS|flags::TWO_SIDED,0.);}}
 self.compounds(scene,g);
 for (i,o) in g.objects.iter().enumerate(){if distance(o.pos,eye)<500.{asset(scene,if o.kind==1{"tank"}else{"fuel_drum"},o.pos,Quat::IDENTITY,1.,3000+i as u32);if o.exploded{part(scene,MeshKey::Sphere,o.pos+Vec3::Y*3.,Vec3::new(5.,7.,5.),Quat::IDENTITY,c("#292b29"),flags::NO_SHADOW,0.);}}}
 for (i,v) in g.vehicles.iter().enumerate(){if distance(v.pos,eye)<350.{let q=Quat::from_rotation_y(-v.yaw)*Quat::from_rotation_x(v.pitch)*Quat::from_rotation_z(v.roll);asset(scene,["technical","jeep","truck","boat"][v.kind as usize],v.pos,q,1.,4000+i as u32);if v.hp<70.{let color=if v.hp<40.{c("#30352f")}else{c("#aaa898")};for k in 0..3{let t=(g.view_time*0.5+k as f32*0.3).fract();part(scene,MeshKey::Sphere,v.pos+Vec3::new(0.,1.6+t*3.,-1.5),Vec3::splat(0.4+t),Quat::IDENTITY,color,flags::NO_SHADOW,0.);}}if night{scene.point_lights.push(PointLight{position:v.pos+Vec3::new(0.,1.2,-3.),color:Vec3::new(2.,1.6,0.7),radius:25.,shadows:false});}}}
 for cache in &g.caches{if !cache.found&&distance(cache.pos,eye)<60.{part(scene,MeshKey::Cube,cache.pos+Vec3::Y*0.25,Vec3::new(0.8,0.4,0.5),Quat::IDENTITY,c("#66694d"),flags::OBJECT,0.);}}
 for (i,n) in g.soldiers.iter().enumerate(){if n.hp<=0.&&distance(n.pos,eye)<95.{part(scene,MeshKey::Cube,n.pos+Vec3::Y*0.2,Vec3::new(0.5,0.3,1.5),Quat::from_rotation_y(n.yaw),c("#59603c"),flags::OBJECT,0.);}else if n.hp>0.&&distance(n.pos,eye)<170.{asset(scene,"ar",n.pos+Vec3::Y*1.15,Quat::from_rotation_y(-n.yaw),0.9,6000+i as u32);}}
 for (i,a) in g.animals.iter().enumerate(){if distance(a.pos,eye)<220.{self.animal(scene,a.pos,a.yaw,g.view_time+a.pos.x,a.kind,i as u32);}}
 for p in &g.peers{if p.present&&p.id!=g.local_id{let color=["#e8443a","#3b82f6","#22c55e","#f5b700"][p.id as usize%4];let mut s=SdfInstance::capsule(p.pos+Vec3::Y*0.4,p.pos+Vec3::Y*1.35,0.26,c(color));s.flags|=flags::OBJECT;scene.sdfs.push(s);asset(scene,"ar",p.pos+Vec3::Y*1.2,Quat::from_rotation_y(-p.yaw),1.,8000+p.id as u32);}}
